import datetime
import uuid
from typing import List, Optional
from sqlalchemy import CheckConstraint, DateTime, Text, UniqueConstraint, func, text
from sqlalchemy.dialects.postgresql import ARRAY, UUID
from sqlalchemy.orm import Mapped, mapped_column
from app.db.session import Base


class SocialConnection(Base):
    __tablename__ = "social_connections"

    # Unique record identifier generated by Postgres
    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )

    # User ID from Neon Auth token (indexed for fast user lookups, no foreign key)
    user_id: Mapped[str] = mapped_column(Text, nullable=False, index=True)

    # OAuth provider name (e.g. linkedin)
    provider: Mapped[str] = mapped_column(Text, nullable=False)

    # Provider unique account identifier (for LinkedIn this is the OpenID sub claim)
    provider_account_id: Mapped[str] = mapped_column(Text, nullable=False)

    # Human-readable account name (e.g. member full name from LinkedIn userinfo)
    account_name: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Encrypted access token (using Fernet symmetric encryption)
    access_token_enc: Mapped[str] = mapped_column(Text, nullable=False)

    # Encrypted refresh token (unused for basic LinkedIn 3-legged OAuth)
    refresh_token_enc: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Timestamp when access token expires
    expires_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False
    )

    # Granted OAuth permission scopes
    scopes: Mapped[List[str]] = mapped_column(ARRAY(Text), nullable=False)

    # Connection lifecycle status: active, expired, or revoked
    status: Mapped[str] = mapped_column(
        Text, nullable=False, server_default="active"
    )

    # Audit timestamps
    connected_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )
    updated_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )

    __table_args__ = (
        CheckConstraint(
            "provider IN ('linkedin')",
            name="ck_social_connections_provider",
        ),
        CheckConstraint(
            "status IN ('active', 'expired', 'revoked')",
            name="ck_social_connections_status",
        ),
        # Each user can only have one connection per provider
        UniqueConstraint(
            "user_id", "provider",
            name="uq_social_connections_user_id_provider",
        ),
        # A single LinkedIn account cannot be linked to multiple AutoPulse users
        UniqueConstraint(
            "provider", "provider_account_id",
            name="uq_social_connections_provider_account",
        ),
    )


class OAuthState(Base):
    __tablename__ = "oauth_states"

    # SHA-256 hex digest of the random state parameter (primary key)
    state_hash: Mapped[str] = mapped_column(Text, primary_key=True)

    # The user initiating the OAuth connection
    user_id: Mapped[str] = mapped_column(Text, nullable=False, index=True)

    # The target provider (e.g. linkedin)
    provider: Mapped[str] = mapped_column(Text, nullable=False)

    # Creation timestamp
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )

    # Expiry timestamp (typically 10 minutes from creation)
    expires_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False
    )

    # When the state was redeemed (null while pending)
    used_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
